SELECT m.notice_id, m.section_id, m.organization_id, m.name, m.raw_identifier, m.scheme, o.identifier, (SELECT group_concat(DISTINCT p.role) FROM tender_version_parties p WHERE p.organization_id = m.organization_id AND p.mention_notice_id = m.notice_id AND p.mention_section_id = m.section_id) AS roles FROM organization_mentions m CROSS JOIN organizations o ON o.id = m.organization_id WHERE m.notice_id IN (46794970, 46792286, 46980990, 46798192)
